  variant?: CardVariant;
  size?: CardSize;
  title?: string;
  subtitle?: string;
  description?: string;
  icon?: ReactNode;
  badgeText?: string;
  badgeColor?: "primary" | "secondary" | "destructive" | "outline";
  showAvatar?: boolean;
  avatarUrl?: string;
  avatarFallback?: string;
  hasHeader?: boolean;
  hasFooter?: boolean;
  hasBorder?: boolean;
  hasShadow?: boolean;
  isClickable?: boolean;
  isDisabled?: boolean;
  isLoading?: boolean;
  primaryActionLabel?: string;
  primaryActionOnClick?: () => void;
  secondaryActionLabel?: string;
  secondaryActionOnClick?: () => void;
  showDismissButton?: boolean;
  onDismiss?: () => void;
  headerRightSlot?: ReactNode;
  footerLeftSlot?: ReactNode;
  content?: ReactNode;
  tags?: string[];
  footerNote?: string;
}

export interface CardContextValue {
  variant: CardVariant;
  size: CardSize;
  disabled?: boolean;
}

export interface CardRootProps extends HTMLAttributes<HTMLDivElement> {
  variant?: CardVariant;
  size?: CardSize;
  disabled?: boolean;
  children?: ReactNode;
}

export interface CardHeaderProps extends HTMLAttributes<HTMLDivElement> {
  children?: ReactNode;
}

export interface CardTitleProps extends HTMLAttributes<HTMLHeadingElement> {
  children?: ReactNode;
}

export interface CardDescriptionProps extends HTMLAttributes<HTMLParagraphElement> {
  children?: ReactNode;
}

export interface CardContentProps extends HTMLAttributes<HTMLDivElement> {
  children?: ReactNode;
}

