import type { ReactNode } from "react";
import type { MegaCardProps } from "../types/card";

export function MegaCard({
  variant = "default",
  size = "md",
  title,
  subtitle,
  description,
  icon,
  badgeText,
  badgeColor = "primary",
  showAvatar = false,
  avatarUrl,
  avatarFallback,
  hasHeader = true,
  hasFooter = false,
  hasBorder = true,
  hasShadow = false,
  isClickable = false,
  isDisabled = false,
  isLoading = false,
  primaryActionLabel,
  primaryActionOnClick,
  secondaryActionLabel,
  secondaryActionOnClick,
  showDismissButton = false,
  onDismiss,
  headerRightSlot,
  footerLeftSlot,
  content,
  tags,
  footerNote,
  className = "",
  ...restProps
}: MegaCardProps) {
  const sizeClasses = {
    sm: "p-3 text-sm",
    md: "p-5 text-base",
    lg: "p-7 text-lg",
  }[size];

  const variantClasses = {
    default: "bg-white text-gray-900",
    bordered: "bg-white border border-gray-200 text-gray-900",
    elevated: "bg-white shadow-lg text-gray-900",
    ghost: "bg-transparent text-gray-900",
  }[variant];

  const borderClass = hasBorder ? "border border-gray-200" : "";
  const shadowClass = hasShadow ? "shadow-md" : "";
  const cursorClass = isClickable ? "cursor-pointer hover:border-gray-400 transition" : "";
  const disabledClass = isDisabled ? "opacity-50 pointer-events-none" : "";

  return (
    <div
      className={`rounded-xl ${variantClasses} ${sizeClasses} ${borderClass} ${shadowClass} ${cursorClass} ${disabledClass} ${className}`}
      {...restProps}
    >
      {isLoading ? (
        <div className="flex items-center justify-center p-8">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600" />
        </div>
      ) : (
        <>
          {hasHeader && (
            <div className="flex items-start justify-between pb-4 border-b border-gray-100 mb-4">
              <div className="flex items-center gap-3">
                {showAvatar && (
                  <div className="h-10 w-10 rounded-full bg-gray-200 flex items-center justify-center overflow-hidden">
                    {avatarUrl ? (
                      <img src={avatarUrl} alt={title || "avatar"} className="h-full w-full object-cover" />
                    ) : (
                      <span className="font-semibold text-gray-600">{avatarFallback || "U"}</span>
                    )}
                  </div>
                )}
                {icon && <div className="text-indigo-600">{icon}</div>}
                <div>
                  {title && <h3 className="font-semibold leading-tight">{title}</h3>}
                  {subtitle && <p className="text-xs text-gray-500">{subtitle}</p>}
                </div>
                {badgeText && (
                  <span
                    className={`text-xs px-2 py-0.5 rounded-full font-medium ${
                      badgeColor === "destructive"
                        ? "bg-red-100 text-red-700"
                        : badgeColor === "secondary"
                        ? "bg-gray-100 text-gray-700"
                        : "bg-indigo-100 text-indigo-700"
                    }`}
                  >
                    {badgeText}
                  </span>
                )}
              </div>
              <div className="flex items-center gap-2">
                {headerRightSlot}
                {showDismissButton && (
                  <button
                    type="button"
                    onClick={onDismiss}
                    className="text-gray-400 hover:text-gray-600 p-1 rounded"
                    aria-label="Dismiss"
                  >
                    ×
                  </button>
                )}
              </div>
            </div>
          )}

          <div className="space-y-3">
            {description && <p className="text-gray-600">{description}</p>}
            {content}
            {tags && tags.length > 0 && (
              <div className="flex flex-wrap gap-1.5 pt-2">
                {tags.map((tag) => (
                  <span key={tag} className="text-xs bg-gray-100 text-gray-600 px-2 py-0.5 rounded">
                    #{tag}
                  </span>
                ))}
              </div>
            )}
          </div>

          {hasFooter && (
            <div className="flex items-center justify-between pt-4 border-t border-gray-100 mt-4">
              <div className="text-xs text-gray-500">
                {footerLeftSlot || footerNote}
              </div>
              <div className="flex items-center gap-2">
                {secondaryActionLabel && (
                  <button
                    type="button"
                    onClick={secondaryActionOnClick}
                    className="px-3 py-1.5 text-sm font-medium text-gray-700 bg-gray-100 hover:bg-gray-200 rounded-lg transition"
                  >
                    {secondaryActionLabel}
                  </button>
                )}
                {primaryActionLabel && (
                  <button
                    type="button"
                    onClick={primaryActionOnClick}
                    className="px-3 py-1.5 text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg transition"
                  >
                    {primaryActionLabel}
                  </button>
                )}
              </div>
            </div>
          )}
        </>
      )}
    </div>
  );
}

